"""Unit tests for the TIP-1034 session primitives against vectors generated by mppx.

tests/fixtures/session/vectors.json comes from tests/fixtures/session/generate_vectors.mjs,
which runs mppx's TypeScript source with ox and viem (see the script for how to rerun it).
"""

from __future__ import annotations

import dataclasses
import json
import re
from pathlib import Path
from typing import Any

import pytest
from pydantic import ValidationError

from mpp.errors import BadRequestError, VerificationError, VerificationFailedError
from mpp.methods.tempo.account import TempoAccount
from mpp.methods.tempo.session import abi, chain, protocol, voucher
from mpp.methods.tempo.session.channel import (
    compute_channel_id,
    expiring_nonce_hash,
    resolve_authorized_signer,
)
from mpp.methods.tempo.session.protocol import (
    ESCROW_ADDRESS,
    ZERO_ADDRESS,
    ChannelDescriptor,
    ClosePayload,
    OpenPayload,
    SessionPayload,
    SignedVoucher,
    TopUpPayload,
    VoucherPayload,
)

VECTORS: dict[str, Any] = json.loads(
    (Path(__file__).parent / "fixtures" / "session" / "vectors.json").read_text()
)
PAYER = VECTORS["addresses"]["payer"]
SIGNER = VECTORS["addresses"]["signer"]


def _descriptor(index: int = 0) -> ChannelDescriptor:
    return ChannelDescriptor.from_wire(VECTORS["channelIds"][index]["descriptor"])


class TestChannel:
    @pytest.mark.parametrize("vector", VECTORS["channelIds"])
    def test_channel_id_matches_mppx(self, vector: dict[str, Any]) -> None:
        descriptor = ChannelDescriptor.from_wire(vector["descriptor"])
        assert (
            compute_channel_id(descriptor, chain_id=vector["chainId"], escrow=vector["escrow"])
            == vector["channelId"]
        )

    def test_channel_id_defaults_to_canonical_escrow(self) -> None:
        vector = next(v for v in VECTORS["channelIds"] if v["escrow"] == ESCROW_ADDRESS)
        descriptor = ChannelDescriptor.from_wire(vector["descriptor"])
        assert compute_channel_id(descriptor, chain_id=vector["chainId"]) == vector["channelId"]

    @pytest.mark.parametrize("vector", VECTORS["transactions"], ids=lambda v: v["label"])
    def test_expiring_nonce_hash_matches_mppx(self, vector: dict[str, Any]) -> None:
        assert expiring_nonce_hash(vector["raw"], vector["sender"]) == vector["expiringNonceHash"]
        if vector["sponsored"]:
            # Fee-payer co-signing must not change the channel identity.
            assert vector["cosignedExpiringNonceHash"] == vector["expiringNonceHash"]
            assert (
                expiring_nonce_hash(vector["cosigned"], vector["sender"])
                == (vector["expiringNonceHash"])
            )

    def test_fee_payer_flag_hashes_a_plain_transaction_as_sponsored(self) -> None:
        plain = next(v for v in VECTORS["transactions"] if v["label"] == "unsponsored")
        sponsored = next(v for v in VECTORS["transactions"] if v["label"] == "sponsored")
        assert (
            expiring_nonce_hash(plain["raw"], plain["sender"], fee_payer=True)
            == (sponsored["expiringNonceHash"])
        )

    def test_expiring_nonce_hash_rejects_other_transaction_types(self) -> None:
        with pytest.raises(ValueError, match="Tempo"):
            expiring_nonce_hash("0x02f8", PAYER)

    def test_resolve_authorized_signer(self) -> None:
        assert resolve_authorized_signer(_descriptor(0)) == PAYER
        assert resolve_authorized_signer(_descriptor(6)) == SIGNER


class TestVoucher:
    @pytest.fixture
    def account(self) -> TempoAccount:
        return TempoAccount.from_key(VECTORS["keys"]["payer"])

    @pytest.mark.parametrize("vector", VECTORS["vouchers"])
    def test_digests_and_signatures_match_mppx(
        self, vector: dict[str, Any], account: TempoAccount
    ) -> None:
        kwargs: dict[str, Any] = {
            "channel_id": vector["channelId"],
            "cumulative_amount": int(vector["cumulativeAmount"]),
            "chain_id": vector["chainId"],
            "escrow": vector["escrow"],
        }
        assert voucher.voucher_digest(**kwargs) == vector["voucherDigest"]
        assert voucher.close_authorization_digest(**kwargs) == vector["closeDigest"]
        assert voucher.sign_voucher(account, **kwargs) == vector["signature"]
        assert voucher.sign_close_authorization(account, **kwargs) == vector["closeSignature"]

    @pytest.mark.parametrize("vector", VECTORS["vouchers"])
    def test_verify_matches_mppx(self, vector: dict[str, Any]) -> None:
        for name, signature in vector["variants"].items():
            signed = SignedVoucher(
                channel_id=vector["channelId"],
                cumulative_amount=int(vector["cumulativeAmount"]),
                signature=signature,
            )
            expected = vector["verify"][name]
            assert (
                voucher.verify_voucher(vector["escrow"], vector["chainId"], signed, PAYER)
                is (expected["payer"])
            ), name
            assert (
                voucher.verify_voucher(vector["escrow"], vector["chainId"], signed, SIGNER)
                is (expected["other"])
            ), name

    @pytest.mark.parametrize("vector", VECTORS["vouchers"])
    def test_close_authorization_is_distinct_from_voucher(self, vector: dict[str, Any]) -> None:
        amount = int(vector["cumulativeAmount"])
        close = SignedVoucher(
            channel_id=vector["channelId"],
            cumulative_amount=amount,
            signature=vector["closeSignature"],
        )
        voucher_as_close = SignedVoucher(
            channel_id=vector["channelId"], cumulative_amount=amount, signature=vector["signature"]
        )
        escrow, chain_id = vector["escrow"], vector["chainId"]
        assert (
            voucher.verify_close_authorization(escrow, chain_id, close, [SIGNER, PAYER])
            is (vector["closeVerify"]["payer"])
        )
        assert (
            voucher.verify_close_authorization(escrow, chain_id, voucher_as_close, [PAYER])
            is (vector["closeVerify"]["voucherSignatureAsClose"])
        )
        assert not voucher.verify_close_authorization(escrow, chain_id, close, [SIGNER])

    def test_signs_with_eth_account(self) -> None:
        from eth_account import Account

        vector = VECTORS["vouchers"][0]
        signature = voucher.sign_voucher(
            Account.from_key(VECTORS["keys"]["payer"]),
            channel_id=vector["channelId"],
            cumulative_amount=int(vector["cumulativeAmount"]),
            chain_id=vector["chainId"],
            escrow=vector["escrow"],
        )
        assert signature == vector["signature"]

    def test_parse_voucher_from_payload_checks_uint96(self) -> None:
        channel_id = "0x" + "11" * 32
        parsed = voucher.parse_voucher_from_payload(channel_id, "5", "0x12")
        assert parsed == SignedVoucher(channel_id=channel_id, cumulative_amount=5, signature="0x12")
        with pytest.raises(ValueError, match="uint96"):
            voucher.parse_voucher_from_payload(channel_id, str(1 << 96), "0x12")


class TestAbi:
    def test_calldata_matches_viem(self) -> None:
        data = VECTORS["abi"]
        descriptor = ChannelDescriptor.from_wire(data["descriptor"])
        calldata = data["calldata"]
        assert (
            abi.encode_open(
                payee=descriptor.payee,
                operator=descriptor.operator,
                token=descriptor.token,
                deposit=123,
                salt=descriptor.salt,
                authorized_signer=descriptor.authorized_signer,
            )
            == calldata["open"]
        )
        assert abi.encode_top_up(descriptor, 456) == calldata["topUp"]
        assert abi.encode_settle(descriptor, 789, "0x" + "12" * 65) == calldata["settle"]
        assert abi.encode_close(descriptor, 1000, 900, "0x" + "34" * 65) == calldata["close"]
        assert abi.encode_request_close(descriptor) == calldata["requestClose"]
        assert abi.encode_withdraw(descriptor) == calldata["withdraw"]
        assert abi.encode_get_channel(descriptor) == calldata["getChannel"]
        assert abi.encode_get_channel_state("0x" + "56" * 32) == calldata["getChannelState"]
        assert (
            abi.encode_get_channel_states_batch(["0x" + "56" * 32, "0x" + "78" * 32])
            == calldata["getChannelStatesBatch"]
        )
        assert abi.encode_compute_channel_id(descriptor) == calldata["computeChannelId"]

    def test_decodes_calldata(self) -> None:
        data = VECTORS["abi"]
        descriptor = ChannelDescriptor.from_wire(data["descriptor"])
        opened = abi.decode_open(data["calldata"]["open"])
        assert opened["deposit"] == 123
        assert opened["payee"] == descriptor.payee
        assert abi.decode_top_up(data["calldata"]["topUp"]) == (descriptor, 456)
        with pytest.raises(ValueError, match="open calldata"):
            abi.decode_open(data["calldata"]["topUp"])
        with pytest.raises(ValueError, match="topUp calldata"):
            abi.decode_top_up(data["calldata"]["topUp"] + "00")

    def test_decodes_results(self) -> None:
        data = VECTORS["abi"]
        state = abi.ChannelStateTuple(settled=10, deposit=100, close_requested_at=1_700_000_000)
        descriptor, decoded = abi.decode_get_channel(data["results"]["getChannel"])
        assert descriptor == ChannelDescriptor.from_wire(data["descriptor"])
        assert decoded == state
        assert abi.decode_get_channel_state(data["results"]["getChannelState"]) == state
        assert abi.decode_get_channel_states_batch(data["results"]["getChannelStatesBatch"]) == [
            state,
            abi.ChannelStateTuple(0, 0, 0),
        ]

    @pytest.mark.parametrize("name", list(VECTORS["abi"]["events"]))
    def test_decodes_events(self, name: str) -> None:
        event = VECTORS["abi"]["events"][name]
        decoded = abi.decode_event(event["topics"], event["data"])
        assert decoded is not None
        assert decoded.name == name
        assert abi.EVENT_TOPICS[name] == event["topics"][0]
        for key, value in event["args"].items():
            expected = int(value) if isinstance(decoded.args[key], int) else value
            assert decoded.args[key] == expected, key

    def test_ignores_unknown_events(self) -> None:
        assert abi.decode_event(["0x" + "00" * 32], "0x") is None


class TestReceipt:
    @pytest.mark.parametrize("vector", VECTORS["receipts"])
    def test_serialization_matches_mppx(self, vector: dict[str, Any]) -> None:
        receipt = protocol.SessionReceipt.from_wire(vector["receipt"])
        assert protocol.serialize_session_receipt(receipt) == vector["serialized"]
        assert protocol.deserialize_session_receipt(vector["serialized"]) == receipt
        assert receipt.to_wire() == vector["receipt"]

    def test_create_session_receipt(self) -> None:
        channel_id = "0x" + "ab" * 32
        receipt = protocol.create_session_receipt(
            challenge_id="c1", channel_id=channel_id, accepted_cumulative=10, spent=4
        )
        assert re.fullmatch(r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z", receipt.timestamp)
        wire = receipt.to_wire()
        assert wire["reference"] == channel_id
        assert wire["acceptedCumulative"] == "10"
        assert wire["spent"] == "4"
        assert "units" not in wire
        assert "txHash" not in wire

    def test_rejects_invalid_receipts(self) -> None:
        with pytest.raises(ValueError, match="Invalid session receipt"):
            protocol.deserialize_session_receipt("not-base64-json")
        with pytest.raises(ValueError, match="Invalid session receipt"):
            protocol.SessionReceipt.from_wire({"method": "tempo", "intent": "charge"})

    def test_need_voucher_event(self) -> None:
        event = protocol.NeedVoucherEvent(
            channel_id="0x01", required_cumulative=5, accepted_cumulative=3, deposit=10
        )
        assert protocol.NeedVoucherEvent.from_wire(event.to_wire()) == event
        assert protocol.format_need_voucher_event(event).startswith("event: payment-need-voucher\n")


class TestMethodSchema:
    def test_request_transform_matches_mppx(self) -> None:
        wire = protocol.definition.normalize_request(
            {
                "amount": "0.25",
                "unitType": "token",
                "currency": "0x20c0000000000000000000000000000000000000",
                "decimals": 6,
                "recipient": "0x70997970C51812dc3A010C7d01b50e0d17dc79C8",
                "suggestedDeposit": "10",
                "minVoucherDelta": "0.01",
                "chainId": 4217,
                "escrowContract": ESCROW_ADDRESS,
                "feePayer": TempoAccount.from_key(VECTORS["keys"]["feePayer"]),
                "sessionProtocol": "v2",
            }
        )
        assert wire == {
            "amount": "250000",
            "unitType": "token",
            "currency": "0x20c0000000000000000000000000000000000000",
            "recipient": "0x70997970C51812dc3A010C7d01b50e0d17dc79C8",
            "suggestedDeposit": "10000000",
            "methodDetails": {
                "escrowContract": ESCROW_ADDRESS,
                "minVoucherDelta": "10000",
                "chainId": 4217,
                "feePayer": True,
                "sessionProtocol": "v2",
            },
        }

    def test_request_always_has_method_details(self) -> None:
        wire = protocol.definition.normalize_request(
            {"amount": "1", "unit_type": "call", "currency": "0x01", "decimals": 6}
        )
        assert wire == {
            "amount": "1000000",
            "unitType": "call",
            "currency": "0x01",
            "methodDetails": {},
        }

    @pytest.mark.parametrize("amount", ["0", "abc", "-1"])
    def test_request_rejects_invalid_amounts(self, amount: str) -> None:
        with pytest.raises(ValidationError):
            protocol.definition.normalize_request(
                {"amount": amount, "unitType": "call", "currency": "0x01", "decimals": 6}
            )

    def test_payloads_round_trip(self) -> None:
        channel_id = "0x" + "11" * 32
        descriptor = _descriptor(0).to_wire()
        payloads: list[dict[str, Any]] = [
            {
                "action": "open",
                "type": "transaction",
                "channelId": channel_id,
                "transaction": "0x76aa",
                "signature": "0x12",
                "descriptor": descriptor,
                "cumulativeAmount": "5",
                "authorizedSigner": PAYER,
            },
            {
                "action": "topUp",
                "type": "transaction",
                "channelId": channel_id,
                "transaction": "0x76bb",
                "descriptor": descriptor,
                "additionalDeposit": "7",
            },
            {
                "action": "voucher",
                "channelId": channel_id,
                "descriptor": descriptor,
                "cumulativeAmount": "9",
                "signature": "0x34",
            },
            {
                "action": "close",
                "channelId": channel_id,
                "descriptor": descriptor,
                "cumulativeAmount": "9",
                "signature": "0x34",
                "closeSignature": "0x56",
            },
        ]
        types = [OpenPayload, TopUpPayload, VoucherPayload, ClosePayload]
        for payload, model in zip(payloads, types, strict=True):
            parsed = protocol.definition.parse_payload(payload).root
            assert isinstance(parsed, model)
            assert parsed.to_wire() == payload
            assert parsed.channel_descriptor() == _descriptor(0)

    def test_payload_rejects_unknown_action_and_bad_fields(self) -> None:
        with pytest.raises(ValidationError):
            SessionPayload.model_validate({"action": "refund", "channelId": "0x" + "11" * 32})
        with pytest.raises(ValidationError):
            SessionPayload.model_validate(
                {
                    "action": "voucher",
                    "channelId": "0x11",
                    "cumulativeAmount": "1",
                    "signature": "0x12",
                }
            )


class TestCredentialTransactions:
    """Server-side checks of client-signed open transactions, on mppx-signed vectors."""

    @staticmethod
    def _open(label: str) -> dict[str, Any]:
        return next(v for v in VECTORS["transactions"] if v["label"] == label)

    def _validate(self, vector: dict[str, Any], **overrides: Any) -> Any:
        descriptor = _descriptor(0)
        kwargs: dict[str, Any] = {
            "serialized_transaction": vector["raw"],
            "chain_id": 1337,
            "escrow_contract": ESCROW_ADDRESS,
            "expected_authorized_signer": ZERO_ADDRESS,
            "expected_channel_id": vector["channelId"],
            "expected_currency": descriptor.token,
            "expected_expiring_nonce_hash": vector["expiringNonceHash"],
            "expected_operator": ZERO_ADDRESS,
            "expected_payee": descriptor.payee,
            "expected_payer": PAYER,
        }
        kwargs.update(overrides)
        return chain.validate_open_credential_transaction(**kwargs)

    def test_validates_open_transaction(self) -> None:
        vector = self._open("unsponsored")
        validated = self._validate(vector)
        assert validated.open_deposit == 5_000_000
        assert validated.expiring_nonce_hash == vector["expiringNonceHash"]
        assert validated.descriptor.payer == PAYER
        assert compute_channel_id(validated.descriptor, chain_id=1337) == vector["channelId"]

    def test_rejects_mismatched_challenge_fields(self) -> None:
        vector = self._open("unsponsored")
        with pytest.raises(VerificationFailedError, match="payee"):
            self._validate(vector, expected_payee=SIGNER)
        with pytest.raises(VerificationFailedError, match="token"):
            self._validate(vector, expected_currency=SIGNER)
        with pytest.raises(VerificationFailedError, match="authorizedSigner"):
            self._validate(vector, expected_authorized_signer=SIGNER)
        with pytest.raises(VerificationFailedError, match="wrong address"):
            self._validate(vector, escrow_contract=SIGNER)
        with pytest.raises(VerificationFailedError, match="channelId does not match"):
            self._validate(vector, expected_channel_id="0x" + "00" * 32)

    def test_rejects_a_wrong_expiring_nonce_hash(self) -> None:
        vector = self._open("unsponsored")
        wrong = "0x" + "00" * 32
        channel_id = compute_channel_id(
            dataclasses.replace(_descriptor(0), expiring_nonce_hash=wrong), chain_id=1337
        )
        with pytest.raises(VerificationFailedError, match="expiringNonceHash"):
            self._validate(
                vector, expected_expiring_nonce_hash=wrong, expected_channel_id=channel_id
            )

    def test_requires_a_fee_payer_for_envelopes(self) -> None:
        with pytest.raises(BadRequestError, match="0x76"):
            self._validate(self._open("sponsored"))

    def test_sponsored_envelope_must_respect_policy(self) -> None:
        sponsor = TempoAccount.from_key(VECTORS["keys"]["feePayer"])
        # The vector's valid_before is far in the future: past the sponsor's window.
        with pytest.raises(VerificationError, match="validity window"):
            self._validate(self._open("sponsored"), fee_payer=sponsor)

    def test_parse_top_up_call_checks_descriptor_and_amount(self) -> None:
        descriptor = ChannelDescriptor.from_wire(VECTORS["abi"]["descriptor"])
        data = VECTORS["abi"]["calldata"]["topUp"]
        assert chain.parse_top_up_call(data, descriptor=descriptor, additional_deposit=456) == (
            descriptor,
            456,
        )
        with pytest.raises(VerificationFailedError, match="descriptor"):
            chain.parse_top_up_call(data, descriptor=_descriptor(0))
        with pytest.raises(VerificationFailedError, match="deposit"):
            chain.parse_top_up_call(data, additional_deposit=1)

    def test_get_channel_event_requires_exactly_one_match(self) -> None:
        event = VECTORS["abi"]["events"]["TopUp"]
        log = {"address": ESCROW_ADDRESS, "topics": event["topics"], "data": event["data"]}
        channel_id = event["args"]["channelId"]
        args = chain.get_channel_event({"logs": [log]}, "TopUp", channel_id, escrow=ESCROW_ADDRESS)
        assert args["newDeposit"] == 5_000_007
        with pytest.raises(VerificationFailedError, match="expected one TopUp"):
            chain.get_channel_event({"logs": [log, log]}, "TopUp", channel_id)
        with pytest.raises(VerificationFailedError, match="expected one TopUp"):
            chain.get_channel_event({"logs": [log]}, "TopUp", channel_id, escrow=SIGNER)

    def test_receipt_and_readback_checks(self) -> None:
        descriptor = _descriptor(0)
        channel_id = compute_channel_id(descriptor, chain_id=1337)
        kwargs: dict[str, Any] = {
            "chain_id": 1337,
            "descriptor": descriptor,
            "emitted_channel_id": channel_id,
            "emitted_deposit": 10,
            "emitted_expiring_nonce_hash": descriptor.expiring_nonce_hash,
            "escrow": ESCROW_ADDRESS,
            "expected_channel_id": channel_id,
            "open_deposit": 10,
        }
        chain.validate_channel_opened_receipt(**kwargs)
        with pytest.raises(VerificationFailedError, match="deposit"):
            chain.validate_channel_opened_receipt(**{**kwargs, "open_deposit": 11})
        chain.validate_open_readback_state(
            emitted_deposit=10,
            state=chain.ChannelState(settled=0, deposit=10, close_requested_at=0),
        )
        with pytest.raises(VerificationFailedError, match="open receipt"):
            chain.validate_open_readback_state(
                emitted_deposit=10,
                state=chain.ChannelState(settled=1, deposit=10, close_requested_at=0),
            )
